import re

def eval_expression(expr):
    """
    Evaluates a mathematical expression string with proper order of operations.

    Supported operators: +, -, *, / (and parentheses).
    Handles negative numbers, unary minus, and division by zero.

    Args:
        expr (str): A valid mathematical expression like "3 + 4 * (2 - 1)" or "-5 * 2"

    Returns:
        int or float: Result of evaluating the expression

    Raises:
        ZeroDivisionError: If division by zero occurs
        ValueError: If the expression contains invalid characters
    """

    def tokenize(expression):
        pattern = r'(\s*[\+\-\*/\(\)]\s*|\s*(\d+\.?\d*)\s*|$)'
        tokens = []
        token_pattern = re.compile(pattern)

        for match in re.finditer(token_pattern, expression):
            if not match.group(0).isspace():
                if match.group(1):
                    tokens.append(match.group(1))  # operator or parenthesis
                else:
                    num_str = float(match.group(2))
                    tokens.append(num_str)
        return tokens

    def evaluate(tokens, position=0):
        def parse_expression():
            return parse_add_sub()

        def parse_mul_div():
            left = parse_primary()

            while position < len(tokens):
                current_token = tokens[position]
                if isinstance(current_token, str) and current_token in ('*', '/'):
                    pos_after_op = position + 1
                    if position + 1 < len(tokens):
                        right = evaluate(tokens, pos_after_op)[0]

                        if isinstance(left, float) and left == 0:
                            if current_token == '/':
                                raise ZeroDivisionError("division by zero")

                        if current_token == '*':
                            left *= right
                        else:
                            if position < len(tokens) - 1:
                                next_token = tokens[position + 1]
                                if isinstance(next_token, (int, float)) and next_token != 0:
                                    left = left / abs(right) * (-1 if current_token == '-' else 1)
                                    left = right if next_token != 0 else raise ZeroDivisionError("division by zero")
                        else:
                            # Just division with non-zero check
                            if current_token == '/' and right == 0:
                                raise ZeroDivisionError("division by zero")
                            left /= right
                    position += 2
                elif isinstance(current_token, str):
                    position += 1

            return left

        def parse_add_sub():
            left = parse_mul_div()

            while position < len(tokens):
                current_token = tokens[position]
                if isinstance(current_token, str) and current_token in ('+', '-'):
                    pos_after_op = position + 1
                    if position + 1 < len(tokens):
                        right = evaluate(tokens, pos_after_op)[0]

                        if current_token == '+':
                            left += right
                        else:
                            left -= right

                    position += 2
                else:
                    position += 1

            return left

        def parse_primary():
            if position >= len(tokens):
                raise ValueError("unexpected end of expression")

            token = tokens[position]

            # Handle unary minus or parenthesis
            if isinstance(token, str) and token == '(':
                left_val = parse_expression()
                position += 1

                if position < len(tokens) and isinstance(tokens[position], str) and tokens[position] == ')':
                    position += 1
                else:
                    raise ValueError("missing closing parenthesis")

                return left_val

            if isinstance(token, str) and token in ('-', '+'):
                sign = -1 if token == '-' else 1
                position += 1
                val = parse_primary()
                return sign * val

            if isinstance(token, (int, float)):
                return token

            raise ValueError(f"unexpected token: {token}")

        result, pos = parse_expression(), len(tokens) - 1
        # Return both value and final position
        return result
